export interface FIFAPlayerData {
  name: string;
  age: number;
  overall: number;
  potential: number;
  position: 'POR' | 'DEF' | 'MED' | 'DEL';
  specificPosition: 'POR' | 'DFC' | 'LI' | 'LD' | 'CAD' | 'CAI' | 'MCD' | 'MC' | 'MCO' | 'MI' | 'MD' | 'EI' | 'ED' | 'DC' | 'SD';
  secondaryPositions?: string[];
  marketValue: number;
  country: string;
  height?: number;
  weight?: number;
  preferredFoot?: 'Left' | 'Right';
  weakFoot?: number;
  skillMoves?: number;
  playStyles?: string[];
  attributes: {
    pace: number;
    shooting: number;
    passing: number;
    dribbling: number;
    defending: number;
    physical: number;
  };
  detailedAttributes?: {
    acceleration: number;
    sprintSpeed: number;
    positioning: number;
    finishing: number;
    shotPower: number;
    longShots: number;
    volleys: number;
    penalties: number;
    vision: number;
    crossing: number;
    freeKickAccuracy: number;
    shortPassing: number;
    longPassing: number;
    curve: number;
    agility: number;
    balance: number;
    reactions: number;
    ballControl: number;
    composure: number;
    interceptions: number;
    headingAccuracy: number;
    defAwareness: number;
    standingTackle: number;
    slidingTackle: number;
    jumping: number;
    stamina: number;
    strength: number;
    aggression: number;
    gkDiving: number;
    gkHandling: number;
    gkKicking: number;
    gkPositioning: number;
    gkReflexes: number;
  };
}

